-- Generated by tools/generate_native_encounter_library.py from the public Bastion Library export.
return {
  ["qvic-cynosure-kvanjji"] = {overview = {"Defeating the first Cynosure brings out his true form and four arbiters. Assign tanks to the arbiters before engaging the new boss; he calls them onto raid members shortly after combat begins.", "Each surviving arbiter can heal Cynosure for 10% of his maximum health and periodically copy his next spell. Killing all four causes the complete arbiter set to return. Plan which arbiters to defeat and which to control while the raid finishes Cynosure."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep separate control of Cynosure and the arbiters. Be ready for four replacements if the entire arbiter set dies."}}, {id = "healer", label = "Healers", tips = {"Expect bursts when the surviving arbiters mimic the same spell. Keep their tanks covered while the raid damages Cynosure."}}, {id = "damage", label = "Damage dealers", tips = {"Coordinate arbiter kills; clearing all four restarts their full set. A healing announcement starts a ten-second delay, but killing its arbiter does not cancel an already queued heal in this script."}}}, phases = {{label = "First form", trigger = "Initial encounter", description = "Defeat the initial Cynosure. His death creates the true boss, who immediately summons all four arbiters."}, {label = "Cynosure and the arbiters", trigger = "True form appears", description = "Control the arbiters while damaging Cynosure. Their independent healing schedules begin 20 to 60 seconds after they appear and then repeat every two and a half minutes."}, {label = "Arbiter replacement", trigger = "All four arbiters die", description = "A repeating five-second check replaces the entire set and begins new healing schedules. Cynosure remains the kill objective."}}, abilities = {{name = "Arbiter healing", summary = "Each announced heal restores 10% of Cynosure’s maximum health after ten seconds.", description = {"The heal is capped at full health. Once announced, the delayed heal does not check whether its arbiter is still alive."}, tags = {}, roles = {}}, {name = "Mimicked spells", summary = "Surviving arbiters periodically copy Cynosure’s next spell.", description = {"Cynosure selects a spell every ten seconds during combat. Every 30 seconds the script readies surviving arbiters to copy the next selection, each against a random target on its own hate list."}, tags = {}, roles = {}}, {name = "Portal energy", summary = "A portal-energy announcement accompanies an additional spell every 90 seconds in combat.", description = {}, tags = {}, roles = {}}}, sections = {{title = "Completion", paragraphs = {"Defeating the true Cynosure removes all four arbiter types and records a 72-hour encounter lockout in the Qvic expedition."}, bullets = {}}}},
  ["qvic-hexxt-ilk-klokk"] = {overview = {"Crossing 45% health starts a twenty-second volley check. A successful check casts random arrow spells at random members of the hate list.", "The scripted branch handles hate-list sizes from one to six and makes that many target selections. Targets are selected independently, so a player may be hit more than once.", "Healing above 45% stops the volley timer and allows it to be armed again on the next downward crossing."}, roles = {}, phases = {}, abilities = {{name = "Arrow volley", summary = "Random-target pressure below 45% health.", description = {"Keep wounded players covered during the twenty-second checks."}, tags = {}, roles = {}}}, sections = {}},
  ["qvic-hexxt-jkak-miq"] = {overview = {"Crossing 45% health starts a twenty-second volley check. A successful check casts random arrow spells at random members of the hate list.", "The scripted branch handles hate-list sizes from one to six and makes that many target selections. Targets are selected independently, so a player may be hit more than once.", "Healing above 45% stops the volley timer and allows it to be armed again on the next downward crossing."}, roles = {}, phases = {}, abilities = {{name = "Arrow volley", summary = "Random-target pressure below 45% health.", description = {"Keep wounded players covered during the twenty-second checks."}, tags = {}, roles = {}}}, sections = {{title = "Weapon choice", paragraphs = {"This NPC reduces incoming archery skill damage by 25%."}, bullets = {}}}},
  ["qvic-hexxt-pvin-nki"] = {overview = {"Crossing 45% health starts a twenty-second volley check. A successful check casts random arrow spells at random members of the hate list.", "The scripted branch handles hate-list sizes from one to six and makes that many target selections. Targets are selected independently, so a player may be hit more than once.", "Healing above 45% stops the volley timer and allows it to be armed again on the next downward crossing."}, roles = {}, phases = {}, abilities = {{name = "Arrow volley", summary = "Random-target pressure below 45% health.", description = {"Keep wounded players covered during the twenty-second checks."}, tags = {}, roles = {}}}, sections = {{title = "Weapon choice", paragraphs = {"This NPC reduces incoming archery skill damage by 25%."}, bullets = {}}}},
  ["qvic-iqthinxa-karnkvi-zoo-event"] = {overview = {"At 75% health, Iqthinxa becomes inactive and summons Rav Gernkki, Rav Marnkki and Rav Karnkki. All three initially attack the boss’s current hate leader, so have their tanks ready to take control.", "Keep the surviving Ravs less than ten percentage points apart in health. An imbalance can make them stronger and force them all onto the wounded Rav’s target. Defeating all three makes Iqthinxa active again."}, roles = {{id = "tank", label = "Tanks", tips = {"Assign one tank to each Rav before pushing the boss to 75%.", "Keep every Rav inside the arena. If their health becomes unbalanced, prepare for them to converge on one tank; regain control as damage balance is restored."}}, {id = "healer", label = "Healers", tips = {"Watch for the frenzy announcement and immediately support the tank being attacked by multiple Ravs."}}, {id = "damage", label = "Damage dealers", tips = {"Compare all surviving Rav health bars and switch targets to keep their spread below ten percentage points.", "Stop attacking Iqthinxa during the Rav stage. Resume when all three Ravs are dead."}}}, phases = {{label = "Iqthinxa", trigger = "100% to 75% health", description = "Fight the boss and prepare the Rav tanks before reaching 75%."}, {label = "Balance the Ravs", trigger = "75% health", description = "Iqthinxa clears his hate list and becomes inactive. Defeat all three Ravs while keeping their health close together and controlling them inside the arena."}, {label = "Finish Iqthinxa", trigger = "All three Ravs defeated", description = "The boss becomes active again. Reestablish tank control and defeat him to complete the encounter."}}, abilities = {{name = "Pack frenzy", summary = "A health gap of ten percentage points can strengthen the Ravs and concentrate their attacks.", description = {"The script checks surviving Rav health pairs. When it selects an injured Rav, all surviving Ravs clear their hate lists and heavily favor that Rav’s current target. Their maximum hits increase and their attack settings change to include area rampage.", "Restoring the health balance signals the Ravs to return to their normal strength."}, tags = {}, roles = {}}, {name = "Arena leash", summary = "Pulling a Rav too far away returns it and its current player target to the arena.", description = {"Ravs more than 250 paces from the arena center are moved back. If the current hate leader is a player, that player is moved with the Rav."}, tags = {}, roles = {}}}, sections = {{title = "Completion", paragraphs = {"Iqthinxa’s death records a 72-hour Zoo Event lockout in the Qvic expedition."}, bullets = {}}}},
  ["poearthb-rathe-council-and-avatar-of-earth"] = {overview = {"Bring all twelve Rathe Council members down within one short kill window, then defeat the Avatar of Earth."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Six council members use the mezzable template and six cannot be mezzed. Divide crowd control and tank assignments before engaging.", "Council members become less accurate and deal less damage at 75%, 50%, 25% and 11% health. Lower them in a controlled order before beginning the final kills.", "Banishment continues while a council member has at least 11% health and is not mezzed. Protect the tank rotation while preparing the council.", "The first death starts a 345-second window. Kill all twelve before fallen members respawn.", "The final council death summons the Avatar of Earth. Defeat it within fifty minutes and interact with the resulting essence."}}}},
  ["poearthb-warlord-gintolaken"] = {overview = {"Defeat three war chieftains to unlock Warlord Gintolaken."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear the Rock Studded Champions, Myrmidons of Stone and Stonefist Clansmen to expose their associated chieftains.", "Defeat Galronar, Awisano and Birak. Their expedition lockouts jointly unlock Gintolaken.", "Gintolaken wipes hate every three minutes and has additional low-chance hate clears between those resets. Keep multiple tanks ready.", "The named stages have fifty-minute hard despawns; the overall event has a three-hour failure limit.", "Victory produces a planar projection for progression credit."}}}},
  ["powater-coirnav-avatar-of-water"] = {overview = {"Clear Coirnav’s elemental armies, defeat three lieutenants, then kill the Avatar of Water within fifteen minutes."}, roles = {}, phases = {{label = "Elemental armies", trigger = "Start, three minutes and five minutes", description = "Clear twenty-five fiends of each of vapor, ice and water."}, {label = "Three lieutenants", trigger = "All fiends defeated", description = "Kill Pwelon, Nrinda and Vamuil."}, {label = "Coirnav", trigger = "All three lieutenants defeated", description = "Handle thirty final adds and defeat the now-vulnerable Avatar before time runs out."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The event begins with twenty-five vaporfiends. Twenty-five icefiends arrive at three minutes and twenty-five waterfiends at five minutes.", "Clear all seventy-five fiends to replace the initial lieutenants with their final combat forms: Pwelon of Vapor, Nrinda of Ice and Vamuil of Water.", "Defeat all three lieutenants to make Coirnav vulnerable. Thirty weaker elemental adds arrive at the same time.", "Assign add tanks for the final wave and immediately establish a tank on Coirnav after its hate reset.", "The entire event has a fifteen-minute limit. Failure banishes the zone’s players; victory summons the Essence of Water."}}}},
  ["riftseekers-chailak"] = {overview = {"Every three seconds during combat, Chailak calls idle Flawless Experimental Battlelords onto a random member of his hate list. Prepare for the linked enemies together.", "After five minutes out of combat, Chailak heals fully, removes his buffs, returns home and clears hate. The Battlelords receive the same reset signal."}, roles = {{id = "tank", label = "Tanks", tips = {"Assign coverage for Battlelords before engaging Chailak."}}}, phases = {}, abilities = {}, sections = {}},
  ["riftseekers-craftmaster-tieranu"] = {overview = {"A ranger at the required epic stage triggers Tieranu by entering the zone while the two-hour event cooldown is clear.", "Tieranu summons Flamegore at 70%, Sizzle at 45% and Hotspot at 20%. Hotspot splits into five small elementals when killed.", "At each 10% health crossing, Tieranu can sacrifice one remaining small elemental and recover 10% of maximum health. Clear those elementals before the final push."}, roles = {}, phases = {{label = "Flamegore", trigger = "70% health", description = "Pick up the first elemental."}, {label = "Sizzle", trigger = "45% health", description = "Control the second elemental alongside any survivors."}, {label = "Hotspot and fragments", trigger = "20% health", description = "Prepare for five small elementals when Hotspot dies."}, {label = "Deny the healing loop", trigger = "10% health", description = "Remove the small elementals so Tieranu cannot consume one to recover health."}}, abilities = {{name = "Elemental spells", summary = "Elementals strip buffs and cast Heatwave at their current target.", description = {"The buff-stripping action repeats every ten seconds after its initial random delay. Heatwave repeats every twenty seconds after its initial delay."}, tags = {}, roles = {}}}, sections = {{title = "Recovery", paragraphs = {"Tieranu initially remains for thirty minutes. Combat pauses that timer; leaving combat starts a five-minute cleanup timer."}, bullets = {}}}},
  ["riftseekers-king-gelaqua-and-the-princes"] = {overview = {"Six princes guard Gelaqua in two linked trios. Each engaged prince activates its portal after five seconds, then every forty to sixty seconds, producing a feran or icy orb.", "Defeating one trio prompts the surviving formation to become aggressive. Kill all six princes to remove the king's protection.", "Keep the princes and king inside their chamber. Their boundary check runs every six seconds and heals, returns and clears hate from any who cross it."}, roles = {}, phases = {{label = "Six princes", trigger = "Opening pull", description = "Cover a linked trio and its feran adds while watching for icy orbs. Prepare for the other trio as the first falls."}, {label = "King Gelaqua", trigger = "All princes defeated", description = "The king becomes vulnerable and seeks a target. His active portals always produce icy orbs, beginning after five seconds and recurring every forty to sixty seconds."}}, abilities = {{name = "Icy orb pursuit", summary = "Orbs move toward the king, then pursue a player.", description = {"Keep pursuing orbs away from the main group. Within three paces of their target they split into four crystals. Crystals immediately cast Gelaqua's Embrace, repeat every four seconds and remain for up to seven minutes."}, tags = {}, roles = {}}}, sections = {}},
  ["riftseekers-queen-pyrilonis-and-the-princesses"] = {overview = {"Six princesses guard Pyrilonis in two linked trios. Their portals activate after five seconds in combat, then every forty to sixty seconds, producing a chimera or fire construct.", "Finishing one trio activates the other formation. All six princesses must die before the queen loses her damage protection.", "Keep these enemies in their chamber. Crossing the boundary triggers a full heal, return home and hate clear at the next six-second check."}, roles = {}, phases = {{label = "Six princesses", trigger = "Opening pull", description = "Control the linked trio, chimera reinforcements and constructs. Be ready for the second formation when the first falls."}, {label = "Queen Pyrilonis", trigger = "All princesses defeated", description = "The queen becomes vulnerable. Her portals always produce fire constructs, beginning after five seconds in combat and recurring every forty to sixty seconds."}}, abilities = {{name = "Fire construct pursuit", summary = "Constructs move to the queen, then pursue a player.", description = {"A construct within three paces of its target casts Pyrilonis' Vengeance and disappears. Keep the pursuit away from the group. It also detonates if it loses a valid target."}, tags = {}, roles = {}}}, sections = {}},
  ["riwwi-arena-turlini-and-the-enslaved-yunjo"] = {overview = {"At the required Riwwi task stage, tell the enslaved yunjo you will \"defy\" the Muramites to begin the first battle and receive its proof container.", "After each battle, combine the required proof and return it to Turlini. Give the resulting challenge token to the enslaved yunjo to summon the next opponents and receive the next container.", "Progress depends on those turn-ins rather than an automatic timer between waves. Turlini requires sufficient faction before accepting proof."}, roles = {}, phases = {{label = "Battles one through four", trigger = "Initial challenge and successive token turn-ins", description = "Face Frothing Hynid, Gibbering Hynid, Handler Bvekh with Highest Hills Cragbeast, then Pfaaxle."}, {label = "Battles five through seven", trigger = "Continue returning proof", description = "Face one stoneworker, then two stone servants, then Master Hviqu with Directed Destroyer and Dominated Bonecrusher."}, {label = "Battles eight through ten", trigger = "Continue returning proof", description = "Face Drax, Qiz and Xnoz together; then Kizki the Slayer; finally six Hexxt and Pixtt opponents."}, {label = "Final proof", trigger = "Tenth battle completed", description = "Return the last proof container to Turlini to complete this part of the escape and receive the follow-up report."}}, abilities = {}, sections = {}},
  ["riwwi-taskmistress-krisz"] = {overview = {"Challenge Riwwi's taskmistress and survive sharply increasing melee pressure near the end."}, roles = {{id = "everyone", label = "Everyone", tips = {"Save defensive coverage and healing for the final health bands."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"With at least 18 raid members in the zone, tell Pixtt Kekken 'dare' while the encounter trigger is available.", "Krisz strengthens her melee attacks at 40%, 30%, 20%, 10% and 5% health; healing above the corresponding recovery thresholds reverses those increases.", "Her 20-minute despawn timer pauses in combat and resumes when combat ends."}}}},
  ["riwwi-viqu-the-blindeye"] = {overview = {"Viqu adds repeated arrow volleys during the lower half of the fight."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the group healthy before each potential volley."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At 45% health, a 20-second timer begins checking for an arrow volley.", "Successful checks fire at random hate-list targets; the script explicitly handles hate-list sizes from one through six.", "Healing back through 45% or leaving combat stops the volley timer."}}}},
  ["dranik-battlemaster-rhorious"] = {overview = {"Rhorious calls his lieutenants and groundpounders into the fight as his health drops."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"At 75%, prepare to collect the named lieutenants.", "At 50%, prepare for the groundpounders to join.", "Defeat the battlemaster and all required supporting enemies to complete the event.", "Keep the event engaged so its recovery and reset timers do not undo progress."}}}},
  ["dranik-bloated-girplan"] = {overview = {"Bloated Girplan rotates bile, breath and presence attacks."}, roles = {}, phases = {}, abilities = {{name = "Bile and breath", summary = "Three recurring casts pressure the group.", description = {}, tags = {"Recurring spells"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep healing available for both Rain of Bile and Fetid Breath, each recurring once a minute after its initial cast.", "Disconcerting Presence recurs every two minutes.", "The combat timers stop on disengagement."}}}},
  ["dranik-discord-fluctuation-trio"] = {overview = {"A necromancer quest releases three named creatures from the Discord Fluctuation."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible necromancer activates the fluctuation through its proximity dialogue.", "Prepare for Rargari, Gornogg and Arlagai to appear together.", "Assign tanks before the trigger and focus the group on one opponent at a time."}}}},
  ["dranik-discordling-dark-animist"] = {overview = {"The dark animist opens with five beasts and a recurring spell rotation."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Collect the five afflicted beasts immediately when the boss appears.", "Prepare for Discordant Feedback and Corporeal Torment while controlling the animals.", "Complete the fight within the thirty-minute combat window."}}}},
  ["dranik-kyv-sharpshooters-jaeth-mihl-and-nass"] = {overview = {"Three linked sharpshooters must be defeated as one encounter."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Engaging one sharpshooter can pull the other two into combat.", "Each becomes mobile at 45% health, so prepare tanks to follow the change.", "Finish all three; the first deaths remove their own loot while another sharpshooter remains."}}}},
  ["dranik-lhranc-and-his-minions"] = {overview = {"Defeat Lhranc's minions before facing the returned shadow knight."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The eligible shadow knight completes Filligno's preparation and says ready to start.", "The first minion leads into a pair; defeating the minions brings out Lhranc.", "Prepare the tank for Harm Touch on engagement and recurring Defiled Insanity afterward."}}}},
  ["dranik-lirah-the-bridgekeeper"] = {overview = {"Lirah fights alongside protectors that can return during combat."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assign add control before pulling the bridgekeeper.", "Lirah repeatedly draws idle protectors into combat and checks for replacements.", "Keep the boss tank stable while controlling renewed protectors.", "A disengagement clears and rebuilds the supporting formation."}}}},
  ["dranik-lirah-the-bridgekeeper-seasonal"] = {overview = {"Lirah fights alongside protectors that can return during combat."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assign add control before pulling the bridgekeeper.", "Lirah repeatedly draws idle protectors into combat and checks for replacements.", "Keep the boss tank stable while controlling renewed protectors.", "A disengagement clears and rebuilds the supporting formation."}}}},
  ["dranik-murkglider-breeder"] = {overview = {"The Murkglider Breeder continually replenishes its spawn during combat."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Collect the first murkglider as the breeder is engaged.", "Further spawn checks occur every twenty seconds while the breeder fights.", "Keep the adds under control while maintaining damage on the breeder."}}}},
  ["dranik-sverins-uisima-rescue"] = {overview = {"Break Sverins' control and subdue Uisima for the ranger rescue."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for linked acolytes and golem-bound spirits alongside the named enemies.", "Keep healing ready for Sverins' recurring Matter Dispersal.", "Lower Uisima to 10% and allow the surrender condition to complete after the other threats are handled.", "The eligible ranger should finish the conversation and quest hand-in after Uisima is freed."}}}},
  ["dranik-tiorpat-tornwing"] = {overview = {"Tiorpat calls members of the surrounding crowd into combat."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear space and identify the surrounding dragorn before starting the confrontation.", "Expect repeated calls for help while Tiorpat fights.", "Collect newly hostile supporters promptly and keep them away from healers.", "A prolonged disengagement can reset the gathering."}}}},
  ["dranik-wren-simsy"] = {overview = {"Wren Simsy summons assassins, with more pressure when a larger group is nearby."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for two assassins as combat starts.", "The opening participant check adds an assassin for each nearby player beyond four.", "Finish the encounter inside the thirty-minute appearance window.", "Wren's death removes the remaining shadowed assassins."}}}},
  ["dranik-zun-muram-volklana"] = {overview = {"Volklana begins rooted, casting terror until his health falls far enough."}, roles = {}, phases = {}, abilities = {{name = "Zun'Muram's Terror", summary = "Repeated casts affect clients within 120 units during the rooted opening.", description = {}, tags = {"Opening phase"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for immediate Terror and further casts every five seconds while the boss remains above 85%.", "At 85%, the terror timer stops and Volklana becomes mobile.", "Have the tank ready to reposition for the mobile fight.", "If his health recovers to 87%, he returns to his initial rooted position."}}}},
  ["illsalin-ritesmaster-verok"] = {overview = {"Ritesmaster Verok seals his chamber and brings a growing spider threat into the battle."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Get the full group inside before pushing Verok below 95%, when the chamber doors lock.", "Seven spider eggs appear at 90%. At 85%, the surrounding spider population is enabled and periodically joins Verok’s hate list.", "At 20%, Verok signals the eggs again for the final stage. Keep add control available during the burn.", "Pulling Verok out of his chamber resets him, clears the spiders and unlocks the doors. Leaving combat also schedules an eighteen-second reset.", "His death clears the event’s eggs and spiders and opens both doors."}}}},
  ["codecay-bertoxxulous"] = {overview = {"Clear the crypt's escalating defenders and kings to summon Bertoxxulous."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assemble before triggering the Spectre of Corruption sequence.", "After the opening delay, rooms activate in succession. Control incoming defenders and track the named kings.", "Clear the required enemies to bring out Bertoxxulous, preserving resources for the final fight.", "The full event has a two-hour failure timer."}}}},
  ["codecay-carprin-deatharn-cycle"] = {overview = {"Break Carprin's guard protection and follow the named sequence deeper into the crypt."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Defeat all three guards before killing Carprin; killing him first brings out a replacement with another guard set.", "Rebuild threat after Carprin's recurring hate wipes.", "Prevent deaths during Avhi Escron: fallen players cause more reanimated reavers to appear.", "Prepare for each named successor and its accompanying enemies before advancing."}}}},
  ["codecay-overlord-banord-paffa"] = {overview = {"Defeat Banord's puslings and subsequent waves to draw out the overlord."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Clear the initial puslings to start the timed wave progression.", "Hold the room through the minion waves and prepare for Banord to become attackable.", "Avoid leaving the final boss idle for an extended period, which can reset the event."}}}},
  ["ruja-rujarkian-hills-adventures-shared-rules"] = {overview = {"Complete the selected Rujarkian Hills adventure objective before its mission timer expires."}, roles = {{id = "everyone", label = "Everyone", tips = {"Use the adventure status dialogue to track the active objective and time remaining."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Assassination adventures unlock their target after the required kill count; defeat that target to finish.", "Kill adventures count eligible deaths, while collection adventures count the requested items when looted.", "NPC strength and rewards scale with the requested level and difficulty; optional named enemies and breakable traps populate the adventure.", "Finishing after the main timer but before closure can award a partial win."}}}},
  ["rujd-prison-break-warden-neyremal-and-high-shaman-yenner"] = {overview = {"Free the prisoners, stop the alarm and defeat the warden and high shaman together."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign control for both final bosses and prepare healing for their 20% frenzies."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Defeat the three taskmasters and use their keys to release the first prisoners.", "The last release calls Prison Guard Talkor. Engage him promptly before his escape sequence completes.", "Clear the prison rooms so the rescuers can free their allies.", "Warden Neyremal and High Shaman Yenner share aggro. Each heals and increases melee damage at 20%. Both must die for the final chest check."}}}},
  ["rujg-flawless-experimental-battlelord"] = {overview = {"Break the research operation before facing a battlelord backed by dormant mutations."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep an alternate tank ready for Throw and reserve add control for mutation activations."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Kill the separated research subjects, then the researchers they unlock, to reveal the final room.", "Every two minutes of combat, the battlelord briefly grows stronger and activates the next mutation group.", "Throw occurs on a one-minute timer and can remove the leading target from hate lists.", "Defeat both final researchers while the battlelord is still alive to satisfy the bonus chest condition.", "After 30 seconds out of combat, the encounter restores its adds."}}}},
  ["unclaimed-dawn-seru-6"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "This is a chapter of the city festival rescue. Ordinary citizens and friendly witnesses stay outside combat. All assignment rules are spoken in the room.", "The highest accepted member fixes a 45-49, 50-54 or 55-60 cohort when the expedition is created; the route and objectives remain the same.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the bell turned away from the petition desk."}}, {id = "healer", label = "Healers", tips = {"Expect one capped group chime after a missed appeal."}}, {id = "damage", label = "Damage dealers", tips = {"Use the open petition desk; move out of the named stamp circle."}}, {id = "everyone", label = "Everyone", tips = {"Petition and stamp assignments never overlap."}}}, phases = {{label = "Objection in time", trigger = "First at 30 seconds; then every 38 seconds after recovery", description = "The bell announces a citizen's appeal and opens a named PETITION desk for 14 seconds. One volunteer uses that desk; the bell's animation does not remove player control. The desk is within 20 paces."}, {label = "The returning stamp", trigger = "At 65% and 30% HP", description = "The adjudicator aims a giant stamp at one of three broad named floor circles. Leave that circle during a 12-second countdown; the other two remain safe and connected. No petition deadline is active."}}, abilities = {{name = "Objection in time", summary = "First at 30 seconds; then every 38 seconds after recovery", description = {"The bell announces a citizen's appeal and opens a named PETITION desk for 14 seconds. One volunteer uses that desk; the bell's animation does not remove player control. The desk is within 20 paces.", "Success: The bell must accept the objection and suspends its 20% ward for 14 seconds.", "Failure: A hollow chime deals 300 magic damage once to the group; the appeal is refiled automatically and the story remains recoverable."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "The returning stamp", summary = "At 65% and 30% HP", description = {"The adjudicator aims a giant stamp at one of three broad named floor circles. Leave that circle during a 12-second countdown; the other two remain safe and connected. No petition deadline is active.", "Success: Characters outside the named circle avoid the stamp.", "Failure: Characters remaining in the circle take 350 magic damage once. There is no root, silence, knockback or follow-up strike."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for The Day the Bells Went Sideways with three to six eligible level-45-or-higher characters. The highest accepted member fixes its 45–49, 50–54 or 55–60 bracket. Higher-bracket replacements cannot join that copy."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-seru-3"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "This is a chapter of the city festival rescue. Ordinary citizens and friendly witnesses stay outside combat. All assignment rules are spoken in the room.", "The highest accepted member fixes a 45-49, 50-54 or 55-60 cohort when the expedition is created; the route and objectives remain the same.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the float stationary when the inspector arrives."}}, {id = "healer", label = "Healers", tips = {"Use the quiet recovery after a junction to restore the group."}}, {id = "damage", label = "Damage dealers", tips = {"Control the one brass inspector during its inspection."}}, {id = "everyone", label = "Everyone", tips = {"Turn the route post called by the witness; both posts are in the arena."}}}, phases = {{label = "The scenic route", trigger = "First at 30 seconds; then every 36 seconds after recovery", description = "The float halts at a broad painted junction. A rescued witness calls LEFT or RIGHT in text; one volunteer turns that named route post within 12 seconds. Both controls are in the same combat courtyard and within 20 paces."}, {label = "Unscheduled inspection", trigger = "At 60% and 25% HP", description = "One 3,500-HP brass inspector begins an 18-second inspection beside the float. Control or destroy it before the stamp lands. The float remains stationary during the assignment."}}, abilities = {{name = "The scenic route", summary = "First at 30 seconds; then every 36 seconds after recovery", description = {"The float halts at a broad painted junction. A rescued witness calls LEFT or RIGHT in text; one volunteer turns that named route post within 12 seconds. Both controls are in the same combat courtyard and within 20 paces.", "Success: The float follows the safe route for 10 seconds, disabling its 15% ward and playing a brief comic fanfare.", "Failure: Its confetti cannon deals 260 magic damage to the group once. It stays in the arena; there is no forced escort reset."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Unscheduled inspection", summary = "At 60% and 25% HP", description = {"One 3,500-HP brass inspector begins an 18-second inspection beside the float. Control or destroy it before the stamp lands. The float remains stationary during the assignment.", "Success: The inspector loses its authority and collapses into harmless bunting.", "Failure: It deals 230 magic damage to the group and withdraws; it never calls city guards or another pack."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for The Day the Bells Went Sideways with three to six eligible level-45-or-higher characters. The highest accepted member fixes its 45–49, 50–54 or 55–60 bracket. Higher-bracket replacements cannot join that copy."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["sseru-lord-inquisitor-seru"] = {overview = {"Lord Inquisitor Seru remains bound to the time chamber."}, roles = {{id = "everyone", label = "Everyone", tips = {"Position the raid inside the chamber and maintain control when he returns to its center."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"During combat, the script checks the chamber boundary every second.", "If he leaves the allowed rectangle, Seru moves back to the chamber center.", "The script does not define a separate health-phase or wave sequence."}}}},
  ["unclaimed-dawn-seru-4"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "This is a chapter of the city festival rescue. Ordinary citizens and friendly witnesses stay outside combat. All assignment rules are spoken in the room.", "The highest accepted member fixes a 45-49, 50-54 or 55-60 cohort when the expedition is created; the route and objectives remain the same.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold the forged double clear of the receipt stands."}}, {id = "healer", label = "Healers", tips = {"Watch the named hound volunteer during the collection run."}}, {id = "damage", label = "Damage dealers", tips = {"Control the receipt hound or guide it into CANCELLED."}}, {id = "everyone", label = "Everyone", tips = {"The contradictory printed time is the forgery; the correct fact is stated explicitly."}}}, phases = {{label = "Spot the impossible receipt", trigger = "First at 30 seconds; then every 36 seconds after recovery", description = "The merchant speaks one explicit fact: either PAID AT DAWN or PAID AT DUSK. Two named ledger stands display matching times and one displays the opposite time. Click the contradictory stand within 16 seconds to expose the forgery. Its full text is repeated in Event Messages, and one error resolves the attempt immediately."}, {label = "The collection run", trigger = "At 65% and 30% HP", description = "One 3,500-HP receipt hound follows the volunteer named by the merchant for 18 seconds. Lead it within 10 paces of the large CANCELLED basket or control/kill it. The basket is on the same flat floor."}}, abilities = {{name = "Spot the impossible receipt", summary = "First at 30 seconds; then every 36 seconds after recovery", description = {"The merchant speaks one explicit fact: either PAID AT DAWN or PAID AT DUSK. Two named ledger stands display matching times and one displays the opposite time. Click the contradictory stand within 16 seconds to expose the forgery. Its full text is repeated in Event Messages, and one error resolves the attempt immediately.", "Success: The forged double loses its 20% ward for 14 seconds while Mella loudly demands a refund.", "Failure: One ink splash deals 280 magic damage to the group; the correct answer is explained. There is no deduction game outside these stated facts."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "The collection run", summary = "At 65% and 30% HP", description = {"One 3,500-HP receipt hound follows the volunteer named by the merchant for 18 seconds. Lead it within 10 paces of the large CANCELLED basket or control/kill it. The basket is on the same flat floor.", "Success: The paper hound crumples into a cancelled receipt.", "Failure: The hound deals 240 magic damage to its named volunteer and despawns; it cannot charm, summon or stun that player."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for The Day the Bells Went Sideways with three to six eligible level-45-or-higher characters. The highest accepted member fixes its 45–49, 50–54 or 55–60 bracket. Higher-bracket replacements cannot join that copy."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-seru-2"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "This is a chapter of the city festival rescue. Ordinary citizens and friendly witnesses stay outside combat. All assignment rules are spoken in the room.", "The highest accepted member fixes a 45-49, 50-54 or 55-60 cohort when the expedition is created; the route and objectives remain the same.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the construct between the ovens without blocking either lever."}}, {id = "healer", label = "Healers", tips = {"A failed proof causes one capped hit; stay in range of the lever volunteer."}}, {id = "damage", label = "Damage dealers", tips = {"Stop the bread roll or use the named flour-sack stop."}}, {id = "everyone", label = "Everyone", tips = {"Read COOL or WARM; both rules are repeated every time."}}}, phases = {{label = "Proof the dough", trigger = "First at 30 seconds; then every 34 seconds after recovery", description = "The construct swells and announces COOL or WARM. Use the matching named oven lever within 12 seconds: COOL closes the hot oven; WARM opens it. A friendly baker states the two rules in the combat message every time. The levers do not teleport players or require an item."}, {label = "Rolling escape", trigger = "At 65% and 30% HP", description = "A single giant bread roll travels down a clearly named side lane for 16 seconds. A volunteer clicks the broad flour-sack stop at that lane's end, or the group destroys the 3,000-HP roll. It does not collide with or knock back players."}}, abilities = {{name = "Proof the dough", summary = "First at 30 seconds; then every 34 seconds after recovery", description = {"The construct swells and announces COOL or WARM. Use the matching named oven lever within 12 seconds: COOL closes the hot oven; WARM opens it. A friendly baker states the two rules in the combat message every time. The levers do not teleport players or require an item.", "Success: The construct deflates, loses its 15% ward for 12 seconds and scatters harmless flour.", "Failure: A flour puff deals 250 fire damage to the group once; no blind effect or vision-obscuring particle is used."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Rolling escape", summary = "At 65% and 30% HP", description = {"A single giant bread roll travels down a clearly named side lane for 16 seconds. A volunteer clicks the broad flour-sack stop at that lane's end, or the group destroys the 3,000-HP roll. It does not collide with or knock back players.", "Success: The roll stops beside the baker, exposing the departure docket's first seal.", "Failure: The roll bursts for 220 magic damage to the group, then disappears; neither doorways nor exits are blocked."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for The Day the Bells Went Sideways with three to six eligible level-45-or-higher characters. The highest accepted member fixes its 45–49, 50–54 or 55–60 bracket. Higher-bracket replacements cannot join that copy."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-seru-1"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "This is a chapter of the city festival rescue. Ordinary citizens and friendly witnesses stay outside combat. All assignment rules are spoken in the room.", "The highest accepted member fixes a 45-49, 50-54 or 55-60 cohort when the expedition is created; the route and objectives remain the same.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Face Quillik away from the three ticket desks."}}, {id = "healer", label = "Healers", tips = {"Plan for one small parcel hit if the queue call is missed."}}, {id = "damage", label = "Damage dealers", tips = {"Control the carbon-copy clerk before its stamp."}}, {id = "everyone", label = "Everyone", tips = {"A single volunteer can handle every desk; no group split is required."}}}, phases = {{label = "Take a number", trigger = "First at 30 seconds; then every 32 seconds after recovery", description = "Quillik announces one of three broad queue lanes: BELL, BROOM or BOOT. One volunteer uses the lane's ticket desk within 12 seconds; all three desks remain within 20 paces and the lane is named in text. The first call is demonstrated by a friendly witness before combat. Any living group member can volunteer; no simultaneous player assignment."}, {label = "Duplicate application", trigger = "At 60% and 25% HP", description = "One 2,500-HP carbon-copy clerk tries to staple a witness into the wrong queue over 18 seconds. Root, mez, stun or kill it. Only this assignment is active."}}, abilities = {{name = "Take a number", summary = "First at 30 seconds; then every 32 seconds after recovery", description = {"Quillik announces one of three broad queue lanes: BELL, BROOM or BOOT. One volunteer uses the lane's ticket desk within 12 seconds; all three desks remain within 20 paces and the lane is named in text. The first call is demonstrated by a friendly witness before combat. Any living group member can volunteer; no simultaneous player assignment.", "Success: The ridiculous queue advances, Quillik pauses melee for 4 seconds and his 15% physical ward falls for 12 seconds.", "Failure: One paper parcel deals 240 magic damage to the group; the next call repeats the rule. No root, stun or permanent queue failure."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Duplicate application", summary = "At 60% and 25% HP", description = {"One 2,500-HP carbon-copy clerk tries to staple a witness into the wrong queue over 18 seconds. Root, mez, stun or kill it. Only this assignment is active.", "Success: The witness steps free and gives Quillik an indignant bow.", "Failure: The clerk deals 200 magic damage once to the group, dissolves, and the witness walks free anyway; the damage is the only penalty."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for The Day the Bells Went Sideways with three to six eligible level-45-or-higher characters. The highest accepted member fixes its 45–49, 50–54 or 55–60 bracket. Higher-bracket replacements cannot join that copy."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["unclaimed-dawn-seru-5"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "This is a chapter of the city festival rescue. Ordinary citizens and friendly witnesses stay outside combat. All assignment rules are spoken in the room.", "The highest accepted member fixes a 45-49, 50-54 or 55-60 cohort when the expedition is created; the route and objectives remain the same.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the Custodian near the stage while preserving curtain access."}}, {id = "healer", label = "Healers", tips = {"Stay in range of the actor volunteer."}}, {id = "damage", label = "Damage dealers", tips = {"Stop the cloth understudy; friendly actors never enter combat."}}, {id = "everyone", label = "Everyone", tips = {"Match the spoken actor name, with no external story knowledge required."}}}, phases = {{label = "An honest entrance", trigger = "First at 30 seconds; then every 38 seconds after recovery", description = "Three friendly actors stand by named stage curtains. The Custodian announces one role and the witness states its true actor's name. One volunteer speaks to that named actor within 14 seconds; all role/name pairs appear together in text. Friendly actors cannot be damaged, charmed or selected as automatic spell targets."}, {label = "Curtain call for the wrong understudy", trigger = "At 60% and 25% HP", description = "One 4,000-HP cloth understudy crosses a marked stage lane over 18 seconds. Control/kill it or use the clearly named CURTAIN rope to stop it. Only one rope and one understudy are active."}}, abilities = {{name = "An honest entrance", summary = "First at 30 seconds; then every 38 seconds after recovery", description = {"Three friendly actors stand by named stage curtains. The Custodian announces one role and the witness states its true actor's name. One volunteer speaks to that named actor within 14 seconds; all role/name pairs appear together in text. Friendly actors cannot be damaged, charmed or selected as automatic spell targets.", "Success: The correct actor unmasks, removes the Custodian's 20% ward for 14 seconds and delivers a different short joke.", "Failure: The Custodian deals 290 magic damage to the group once. It never copies a player's spellbook, gear or class."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Curtain call for the wrong understudy", summary = "At 60% and 25% HP", description = {"One 4,000-HP cloth understudy crosses a marked stage lane over 18 seconds. Control/kill it or use the clearly named CURTAIN rope to stop it. Only one rope and one understudy are active.", "Success: The company takes a bow; the lane clears immediately.", "Failure: The understudy deals 250 magic damage once to the group and exits. No blind, forced illusion or blocked camera."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The group leader asks Keeper Avel for The Day the Bells Went Sideways with three to six eligible level-45-or-higher characters. The highest accepted member fixes its 45–49, 50–54 or 55–60 bracket. Higher-bracket replacements cannot join that copy."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["sncrematory-gzifa-the-pure-one"] = {overview = {"Gather the four spirits and follow their essences to reveal Gzifa."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the remains together and allow the traveling essences to complete their route."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"One character must carry all four required remains into the trigger area; the items cannot be divided between players.", "Defeat Talakoi, Ngozi, Mabiki and Yogundi so their ghostly essences can travel to the crystal room.", "Once all four essences arrive, Gzifa spawns after a ten-second delay."}}}},
  ["snlair-sewers-of-nihilia-lair-tool-recovery"] = {overview = {"Recover Alej Leraji's tools before his survival timer expires."}, roles = {{id = "everyone", label = "Everyone", tips = {"Clear and search all three tool rooms, then return promptly to Alej."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Give Alej the qualifying seal to populate the tool rooms and start the rescue.", "The entrance, cocoon and waterwheel rooms each place a tool on one randomly selected event enemy.", "Alej warns after 50 minutes; ten minutes later the event fails if he has not been rescued."}}}},
  ["snpool-sewers-of-nihilia-slime-cube"] = {overview = {"Help Utandi recover his map by defeating a cube that divides into fragments."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep add control ready when the large cube dies."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"With the pool task active, follow Utandi's dialogue through 'find it' to spawn the Slime Cube.", "Killing the cube creates six fragments at its death position.", "Recover the four map pieces and return them to Utandi for the task progression."}}}},
  ["snplant-ancient-kayserops-sewers-stonemite-event"] = {overview = {"Draw Ancient Kayserops out by defeating the aged stonemites."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare for the boss before killing the final aged stonemite."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Hail Ansharu with the plant task active to spawn the nine aged stonemites.", "The ninth death brings Ancient Kayserops into the room.", "Defeating Kayserops closes the expedition to additional members and updates the plant and sewer progression tasks."}}}},
  ["sirens-a-twitching-swordfish"] = {overview = {"Weaken the twitching swordfish so the ranger can attempt a capture."}, roles = {{id = "everyone", label = "Everyone", tips = {"Stop excessive damage below 25% while the ranger maintains the required weapon."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Entering combat sets a 25% health trigger.", "Below that trigger, a check every 15 seconds has a one-in-four chance to inspect damaging rangers with the required capture weapon in their primary slot.", "A successful capture grants the quest result and depops the fish. Killing it instead casts Epidermal Rot."}}}},
  ["skyfire-rithnok-the-tormented"] = {overview = {"Release Rithnok from his torment after Dry Sapara's paladin epic trigger."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare the tank for the opening Harm Touch."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"A paladin on the qualifying epic steps carrying the required seal can hail Dry Sapara to spawn Rithnok.", "Rithnok opens combat with Harm Touch.", "He depops after 30 minutes from spawn."}}}},
  ["skyfire-talendor-seasonal"] = {overview = {"Talendor pressures nearby players with flame bursts and repeated random-target attacks."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the raid stable through the timer phase, then use the final vulnerability window."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Flameburst pulses every 12 seconds within 60 range.", "Every 25 seconds, Incinerate attempts attacks on three randomly chosen hate targets.", "At 20% health the scripted timers stop and both one- and two-handed piercing and blunt attacks become more effective."}}}},
  ["skyshrine-lord-yelinak-seasonal"] = {overview = {"Read Yelinak's storm warnings, shelter during his shield and survive increasingly fast ground mechanics."}, roles = {{id = "everyone", label = "Everyone", tips = {"Move to the marked boundaries rather than following a moving tank.", "Finish or cancel spells before Silence resolves."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Ground warnings give eight seconds: leave the marked 32-range storm strike, shelter within the marked 65-range storm eye, or stop casting for Silence.", "At 65% health, Yelinak becomes protected for a fixed storm-shield sequence. Gather within 60 range, then move beyond the inner 35-range ring when warned.", "The shield ends after 23 seconds. At 30% and 10% health, ground mechanics accelerate."}}}},
  ["sleeper-awakening-the-sleeper"] = {overview = {"Break the warders' hold to awaken Kerafyrm in the legacy Sleeper event."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare everyone in the zone before the last warder falls, because Kerafyrm's aggression reaches beyond the immediate room."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The wardstone checks for all four warders to be absent before awakening the Sleeper.", "The Sleeper is replaced by Kerafyrm, who adds every non-GM player in the zone to his hate list every ten seconds.", "Kerafyrm's script removes him after four hours.", "The wardstone records an instance-scoped seven-day awakening marker; warder respawns reset that marker and restore the sleeping form."}}}},
  ["sleeper-master-of-the-guard"] = {overview = {"The Master of the Guard activates paired sentries during combat."}, roles = {{id = "everyone", label = "Everyone", tips = {"Pick up each sentry pair before it reaches the rest of the raid."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The first pair activates three seconds after combat begins.", "Three further pairs activate at 50-second intervals.", "Five minutes out of combat removes active sentries and restores the dormant formation."}}}},
  ["sleeper-sleep-walking-expedition"] = {overview = {"Sleep Walking is a fabled Sleeper's Tomb expedition whose boss availability follows saved lockouts."}, roles = {{id = "everyone", label = "Everyone", tips = {"Check expedition lockouts before choosing the next target; use the separate scripted boss guides for detailed mechanics."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The expedition configuration allows 6 to 96 players and a six-hour instance.", "The gatekeeper replaces the normal named population with fabled bosses whose lockouts have not been earned.", "Each named completion records a five-day lockout. The finale includes the fabled awakened dragon."}}}},
  ["sleeper-the-fabled-kerafyrm-the-awakened"] = {overview = {"The fabled awakened dragon alternates a leading-target attack with a slower area attack."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep tank healing and raid recovery ready for overlapping spell timers."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Single-target casting begins 12 to 18 seconds after spawn and then repeats every 35 seconds.", "The area spell begins 20 to 28 seconds after spawn and then repeats every 60 seconds.", "Death signals the Sleep Walking controller to record the finale lockout."}}}},
  ["sleeper-the-fabled-master-of-the-guard"] = {overview = {"The fabled Master of the Guard uses the paired-sentry sequence in Sleep Walking."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign add tanks for each pair while maintaining control of the Master."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The first sentry pair activates three seconds after engagement.", "Three further pairs activate at 50-second intervals.", "Five minutes out of combat restores the sentry formation; the fabled death callback records the expedition boss lockout."}}}},
  ["eastkorlacha-bloodeye"] = {overview = {"Bloodeye calls two Ragepaw commanders at 75% health."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Have two adds covered when the boss reaches 75%.", "Control Stonebite and Ironfur as they join the encounter.", "Keep the fight in Bloodeye's area to avoid the out-of-bounds reset."}}}},
  ["ssratemple-emperor-ssraeshza-and-the-blood"] = {overview = {"Defeat the Blood to awaken the Emperor, then control his linked royal guards."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep the guard team organized through the delay between the Blood and the Emperor."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The Blood creates a protected Emperor and shares aggro with eight guards.", "Killing the Blood starts a randomized three-to-five-minute Emperor activation delay.", "The active Emperor re-engages any idle guards every 30 seconds.", "A one-hour reset timer restores the Emperor's protected state."}}}},
  ["ssratemple-rhag-cycle-arch-lich"] = {overview = {"Advance through the Rhag cycle to reveal the Arch Lich."}, roles = {{id = "everyone", label = "Everyone", tips = {"Regroup before each boss death because the next guarded encounter spawns immediately."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Rhag`Zhezum's death spawns Rhag`Mozdezh with four guards.", "Rhag`Mozdezh's death spawns the Arch Lich and another guard group.", "The cycle stores its current stage per instance so progression can be restored after a zone restart."}}}},
}
